export function getRuleDetails(code) {
  const c = Number(code);
  const category = getRuleCategory(c);

  let targetModule = "اعتبارات هزینه‌ای و تملک / صورت‌های مالی";
  let affectedMoeins = [];

  if (category === "expense") {
    targetModule = "اعتبارات هزینه‌ای (جاری)";
    affectedMoeins = ["41001 (اعتبار هزینه مصوب)", "41005 (اختصاصی هزینه)", "91001 (مصوب هزینه)", "91003 (انتقالی هزینه)", "94001 (حواله هزینه)", "94003 (حواله انتقالی)", "98003 (پیش‌پرداخت هزینه)", "92503 (واخواهی)", "93503 (کسری ابواب‌جمعی)"];
  } else if (category === "capital") {
    targetModule = "اعتبارات تملک دارایی‌های سرمایه‌ای و مالی (عمرانی)";
    affectedMoeins = ["41003 (اعتبار سرمایه‌ای مصوب)", "41006 (اختصاصی سرمایه‌ای)", "91002 (مصوب سرمایه‌ای)", "91004 (انتقالی سرمایه‌ای)", "94002 (حواله سرمایه‌ای)", "94004 (حواله انتقالی)", "98004 (پیش‌پرداخت/موجودی سرمایه‌ای)", "92504 (واخواهی)", "93504 (کسری ابواب‌جمعی)"];
  } else if (category === "financial") {
    targetModule = "صورت‌های مالی اساسی و یادداشت‌های توضیحی سناما";
    affectedMoeins = ["11101 (بانک‌ها)", "11301 (تنخواه)", "11504 (ذخیره مشکوک‌الوصول کوتاه مدت)", "12004 (ذخیره مشکوک‌الوصول بلند مدت)", "27002 (سایر ذخایر)", "24001 (مزایای پایان خدمت)", "24002 (ذخیره مرخصی)", "160101-160501 (دارایی‌های ثابت)"];
  } else {
    targetModule = "مشترک / ترکیبی (اعتبارات هزینه‌ای، تملک و صورت‌های مالی)";
    affectedMoeins = ["۴۱۰۰۱ / ۴۱۰۰۳ (اعتبار مصوب)", "۹۱۰۰۱ / ۹۱۰۰۲ (مصوب هزینه و سرمایه‌ای)", "۹۴۰۰۱ / ۹۴۰۰۲ (حواله‌ها)", "۱۱۵۰۴ / ۱۲۰۰۴ (ذخایر مطالبات)", "۲۷۰۰۲ (سایر ذخایر)"];
  }

  return { code: c, category, targetModule, affectedMoeins };
}

